function divide(a, b) {
  if (b === 0) throw new Error('Division by zero');
  return a / b;
}

try {
  console.log(divide(10, 2));
  console.log(divide(1, 0));
} catch (err) {
  console.error('Caught:', err.message);
} finally {
  console.log('cleanup always runs');
}

