def divide(a, b):
    if b == 0:
        raise ZeroDivisionError('division by zero')
    return a / b

try:
    print(divide(10, 2))
    print(divide(1, 0))
except ZeroDivisionError as e:
    print('Caught:', e)
finally:
    print('cleanup always runs')
